import json
h,w=18,15
g=[[0]*w for _ in range(h)]
shape={(0,2),(0,3),(1,1),(1,4)}|{(2,c) for c in range(6)}
for layer,color in enumerate([2,3,1,8,7]):
    top=3*layer
    for dr,dc in shape:
        g[top+dr][3+dc]=color
assert len(g)==18 and all(len(row)==15 for row in g)
print(json.dumps(g,separators=(',',':')))
